import subprocess, os, pty
def run_tty(args, env_extra={}, inp=b""):
    master, slave = pty.openpty()
    env=dict(os.environ); 
    for k,v in env_extra.items():
        if v is None: env.pop(k,None)
        else: env[k]=v
    p = subprocess.Popen(args, stdout=slave, stderr=slave, stdin=subprocess.PIPE, env=env)
    os.close(slave)
    if inp:
        p.stdin.write(inp)
    try:
        p.stdin.close()
    except: pass
    out=b""
    while True:
        try:
            d=os.read(master,4096)
            if not d: break
            out+=d
        except OSError: break
    p.wait()
    return p.returncode, out

# NO_COLOR presence regardless value disables default tty color, but -t 1 overrides? Test tty + NO_COLOR + -t1
for extra_args, env in [
 (["-t","1"], {"NO_COLOR":"1"}),
 (["-t","0"], {}),
 (["-t","1"], {}),
 ([], {"NO_COLOR":None}),
 ([], {"CLICOLOR":"0"}),
 ([], {"CLICOLOR_FORCE":"1"}),
]:
    # non-tty also check clicolor_force?
    rc,out = run_tty(["./executable"]+extra_args+["assets/tiny.bin"], env)
