use std::io::{self, Write};

pub mod function_output;

/// The textual representation used for each input byte.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum OctetFormat {
    Octal,
    LowerHex,
    UpperHex,
    Binary,
}

impl OctetFormat {
    pub fn from_option(value: Option<&String>) -> Self {
        match value.map(String::as_str) {
            Some("o") => Self::Octal,
            Some("X") => Self::UpperHex,
            Some("b") => Self::Binary,
            _ => Self::LowerHex,
        }
    }
}

fn colour_code(byte: u8) -> u8 {
    // Black would be invisible on a typical dark terminal, so byte
    // value zero is rendered with the otherwise unused colour 22.
    if byte == 0 {
        22
    } else {
        byte
    }
}

fn octet_text(byte: u8, format: OctetFormat, prefix: bool) -> String {
    match (format, prefix) {
        (OctetFormat::Octal, true) => format!("0o{:04o}", byte),
        (OctetFormat::Octal, false) => format!("{:04o}", byte),
        (OctetFormat::LowerHex, true) => format!("0x{:02x}", byte),
        (OctetFormat::LowerHex, false) => format!("{:02x}", byte),
        (OctetFormat::UpperHex, true) => format!("0x{:02X}", byte),
        (OctetFormat::UpperHex, false) => format!("{:02X}", byte),
        (OctetFormat::Binary, true) => format!("0b{:08b}", byte),
        (OctetFormat::Binary, false) => format!("{:08b}", byte),
    }
}

fn ascii_text(byte: u8) -> char {
    if byte.is_ascii_graphic() || byte == b' ' {
        byte as char
    } else {
        '.'
    }
}

fn write_coloured<W: Write>(
    output: &mut W,
    byte: u8,
    text: &str,
    colour: bool,
) -> io::Result<()> {
    if colour {
        write!(output, "\u{1b}[38;5;{}m{}\u{1b}[0m", colour_code(byte), text)
    } else {
        write!(output, "{}", text)
    }
}

/// Write the normal hexadecimal/selected-format dump.
pub fn hex_output<W: Write>(
    writer: W,
    data: &[u8],
    columns: usize,
    format: OctetFormat,
    prefix: bool,
    colour: bool,
) -> io::Result<()> {
    let mut output = io::BufWriter::new(writer);
    let row_width = columns.max(1);
    let mut row_count = 0usize;
    let mut ascii = Vec::new();

    write!(output, "0x{:06x}: ", 0)?;
    for (index, &byte) in data.iter().enumerate() {
        let token = octet_text(byte, format, prefix);
        write_coloured(&mut output, byte, &token, colour)?;
        write!(output, " ")?;
        ascii.push(byte);
        row_count += 1;

        if row_count == row_width {
            for &text_byte in &ascii {
                let character = ascii_text(text_byte).to_string();
                write_coloured(&mut output, text_byte, &character, colour)?;
            }
            writeln!(output)?;
            write!(output, "0x{:06x}: ", index + 1)?;
            ascii.clear();
            row_count = 0;
        }
    }

    output.flush()?;
    // This intentionally uses the same style of dynamic formatting
    // operation as the rest of the padding calculation; as in the
    // behaviour being reproduced, an absurdly large width is rejected
    // by the formatting machinery.
    let padding = format!("{:1$}", "", (columns - row_count) * 5);
    write!(output, "{}", padding)?;
    for &text_byte in &ascii {
        let character = ascii_text(text_byte).to_string();
        write_coloured(&mut output, text_byte, &character, colour)?;
    }
    writeln!(output)?;
    writeln!(output, "   bytes: {}", data.len())?;
    output.flush()
}

/// Write `data` as an array literal in one of the supported languages.
pub fn array_output<W: Write>(
    writer: W,
    data: &[u8],
    columns: usize,
    array_format: &str,
