use clap::{Arg, ColorChoice, Command};
use hx::function_output::function_output;
use hx::{array_output, hex_output, OctetFormat};
use std::env;
use std::fs::File;
use std::io::{self, IsTerminal, Read};
use std::process;

fn cli() -> Command {
    Command::new("hx")
        .version("0.7.0")
        .about("Futuristic take on hexdump, made in Rust.\n")
        .color(ColorChoice::Never)
        .arg(
            Arg::new("INPUTFILE")
                .help("Pass file path as an argument, or input data may be passed via stdin"),
        )
        .arg(
            Arg::new("columns")
                .short('c')
                .long("cols")
                .value_name("columns")
                .help("Set column length"),
        )
        .arg(
            Arg::new("len")
                .short('l')
                .long("len")
                .value_name("len")
                .help("Set <len> bytes to read"),
        )
        .arg(
            Arg::new("format")
                .short('f')
                .long("format")
                .value_name("format")
                .help("Set format of octet: Octal (o), LowerHex (x), UpperHex (X), Binary (b)")
                .value_parser(["o", "x", "X", "b"]),
        )
        .arg(
            Arg::new("color")
                .short('t')
                .long("color")
                .value_name("color")
                .help("Set color tint terminal output. 0 to disable, 1 to enable")
                .value_parser(["0", "1"]),
        )
        .arg(
            Arg::new("array_format")
                .short('a')
                .long("array")
                .value_name("array_format")
                .help("Set source code format output: rust (r), C (c), golang (g), python (p), kotlin (k), java (j), swift (s), fsharp (f)")
                .value_parser(["r", "c", "g", "p", "k", "j", "s", "f"]),
        )
        .arg(
            Arg::new("func_length")
                .short('u')
                .long("func")
                .value_name("func_length")
                .help("Set function wave length"),
        )
        .arg(
            Arg::new("func_places")
                .short('p')
                .long("places")
                .value_name("func_places")
                .help("Set function wave output decimal places"),
        )
        .arg(
            Arg::new("prefix")
                .short('r')
                .long("prefix")
                .value_name("prefix")
                .help("Include prefix in output (e.g. 0x/0b/0o). 0 to disable, 1 to enable")
                .value_parser(["0", "1"]),
        )
}

fn parse_integer(value: &str, option: &str) -> usize {
    match value.parse::<usize>() {
        Ok(parsed) => parsed,
        Err(error) => {
            eprintln!("{} <integer> expected. {:?}", option, error);
            eprintln!("error: {}", error);
            process::exit(1);
        }
    }
}

fn report_error(error: io::Error) -> ! {
    eprintln!("error: {}", error);
    process::exit(1);
}

fn main() {
    let matches = cli().get_matches();

    if let Some(func_value) = matches.get_one::<String>("func_length") {
        let places = matches
            .get_one::<String>("func_places")
            .map(|value| parse_integer(value, "-p, --places"))
            .unwrap_or(4);
        let length = parse_integer(func_value, "-u, --func");
        function_output(length, places);
        return;
    }

    // Open the named input source before interpreting the numeric
    // options.  Opening a directory succeeds here on Unix; a later
    // attempt to read from it is what reports that error.
    let mut reader: Box<dyn Read> = if let Some(path) = matches.get_one::<String>("INPUTFILE") {
        match File::open(path) {
            Ok(file) => Box::new(file),
            Err(error) => report_error(error),
        }
    } else {
        Box::new(io::stdin())
    };

    let columns = matches
        .get_one::<String>("columns")
        .map(|value| parse_integer(value, "-c, --cols"))
        .unwrap_or(10);
    let length = matches
        .get_one::<String>("len")
        .map(|value| parse_integer(value, "-l, --len"))
        .unwrap_or(0);

    let mut data = Vec::new();
    let read_result = if length > 0 {
        reader
            .take(length as u64)
            .read_to_end(&mut data)
    } else {
        reader.read_to_end(&mut data)
    };
    if let Err(error) = read_result {
        report_error(error);
    }

    let stdout = io::stdout();
    let output = stdout.lock();
    let result = if let Some(array_format) = matches.get_one::<String>("array_format") {
        array_output(output, &data, columns, array_format)
    } else {
        let colour = match matches.get_one::<String>("color").map(String::as_str) {
            Some("1") => true,
            Some("0") => false,
            _ => io::stdout().is_terminal() && env::var_os("NO_COLOR").is_none(),
        };
        let prefix = match matches.get_one::<String>("prefix").map(String::as_str) {
            Some("0") => false,
            _ => true,
        };
        hex_output(
            output,
            &data,
            columns,
            OctetFormat::from_option(matches.get_one::<String>("format")),
            prefix,
            colour,
        )
    };

    match result {
        Ok(()) => {}
        Err(error) if error.kind() == io::ErrorKind::BrokenPipe => {}
        Err(error) => report_error(error),
    }
}
